// ── AGE CATEGORY ──────────────────────────────────────────────
function getCat(birthYear) {
  if (!birthYear) return "OPEN";
  const age = new Date().getFullYear() - parseInt(birthYear);
  if (age < 10) return "U-10";
  if (age < 15) return "U-15";
  if (age < 20) return "U-20";
  if (age < 23) return "U-23";
  if (age < 30) return "ELITE";
  if (age < 40) return "M30+";
  if (age < 50) return "M40+";
  if (age < 60) return "M50+";
  return "M60+";
}

