// ═══════════════════════════════════════════════════════════════
// AUTH SCREEN
// ═══════════════════════════════════════════════════════════════
function AuthScreen({ users, onLogin, onRegister, onGuest, site: authSite }) {
  const [mode, setMode]   = useState("login");
  const [form, setForm]   = useState({ name:"", email:"", pass:"", pass2:"", year:"" });
  const [errs, setErrs]   = useState({});
  const [showPw, setShowPw] = useState(false);
  const [busy, setBusy]   = useState(false);
  const sf = k => e => setForm(f => ({ ...f, [k]: e.target.value }));

  function validate() {
    const e = {};
    if (!form.email || !form.email.includes("@")) e.email = "Wpisz prawidłowy email";
    if (!form.pass) e.pass = "Hasło jest wymagane";
    if (mode === "register") {
      if (!form.name)  e.name = "Imię i nazwisko jest wymagane";
      if (form.pass.length < 6)  e.pass  = "Hasło min. 6 znaków";
      if (form.pass !== form.pass2) e.pass2 = "Hasła się nie zgadzają";
      const y = parseInt(form.year);
      if (!y || y < 1930 || y > new Date().getFullYear()) e.year = "Podaj rok urodzenia (np. 1985)";
    }
    setErrs(e);
    return Object.keys(e).length === 0;
  }

  async function submit() {
    if (!validate()) return;
    setBusy(true);
    try {
      if (mode === "login") {
        const { error } = await sb.auth.signInWithPassword({ email: form.email, password: form.pass });
        if (error) { setErrs({ email: "Nieprawidłowy email lub hasło" }); return; }
        onGuest();
      } else {
        const { error } = await sb.auth.signUp({
          email: form.email, password: form.pass,
          options: { data: { name: form.name, birth_year: form.year } },
        });
        if (error) {
          if (error.message.includes("already")) setErrs({ email: "Ten email jest już zajęty" });
          else setErrs({ email: error.message });
          return;
        }
        onGuest();
      }
    } catch (e) {
      setErrs({ email: "Błąd połączenia z serwerem" });
    } finally {
      setBusy(false);
    }
  }

  const cat = form.year && parseInt(form.year) > 1930 ? getCat(form.year) : "";

  return (
    <div style={{ minHeight:"100vh", background:BG, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:"24px 20px", position:"relative", overflow:"hidden" }}>
      <div style={{ position:"absolute", top:"-10%", left:"50%", transform:"translateX(-50%)", width:600, height:600, background:"radial-gradient(circle, rgba(255,0,38,0.10) 0%, transparent 60%)", pointerEvents:"none" }} />

      <div style={{ textAlign:"center", marginBottom:34, position:"relative", animation:"fadeUp 0.5s " + SPR }}>
        <div style={{ width:110, height:110, borderRadius:"50%", border:"2px solid " + RED, background:REDD, display:"flex", alignItems:"center", justifyContent:"center", margin:"0 auto 16px", boxShadow:"0 0 40px " + REDG, overflow:"hidden" }}>
          <ClubLogo site={authSite || INIT_SITE} size={96} />
        </div>
        <h1 style={{ fontFamily:FT, fontSize:26, fontWeight:700, letterSpacing:3.5, margin:"0 0 5px", color:TEXT }}>WATAHA MILICZ</h1>
        <p style={{ color:SUB, fontSize:11, margin:0, letterSpacing:2.4, fontFamily:FT, textTransform:"uppercase" }}>BARYCZ BIKE COLLECTIVE</p>
      </div>

      <div style={{ background:SURF, backgroundImage:CARD_GRAD, borderRadius:20, padding:"24px 22px", width:"100%", maxWidth:400, border:"1px solid " + BDR, marginBottom:14, boxShadow:"0 16px 48px rgba(0,0,0,0.5)", position:"relative", animation:"fadeUp 0.55s " + SPR + " 0.08s both" }}>
        <div style={{ display:"flex", background:SURF2, borderRadius:11, padding:3, marginBottom:22, gap:3 }}>
          {[["login","Zaloguj się"],["register","Rejestracja"]].map(([m, l]) => (
            <button key={m} onClick={() => { setMode(m); setErrs({}); }} className="no-tap"
              style={{ flex:1, background: mode === m ? RED : "transparent", border:"none", borderRadius:9, padding:"9px 0", color: mode === m ? "#fff" : SUB, fontFamily:FT, fontWeight:600, fontSize:12, letterSpacing:1, cursor:"pointer", textTransform:"uppercase", boxShadow: mode === m ? "0 4px 14px rgba(255,0,38,0.35)" : "none", transition: "background 0.25s ease, color 0.25s ease, box-shadow 0.25s ease" }}>
              {l}
            </button>
          ))}
        </div>

        {mode === "register" && <TInput label="Imię i nazwisko" value={form.name} onChange={sf("name")} error={errs.name} placeholder="Jan Kowalski" />}
        <TInput label="Email" type="email" value={form.email} onChange={sf("email")} error={errs.email} placeholder="jan@example.pl" />

        <div style={{ marginBottom:13 }}>
          <label style={{ display:"block", marginBottom:6, fontSize:10, color:SUB, textTransform:"uppercase", letterSpacing:1.6, fontFamily:FT, fontWeight:600 }}>HASLO</label>
          <div style={{ position:"relative" }}>
            <input type={showPw ? "text" : "password"} value={form.pass} onChange={sf("pass")} placeholder="••••••••" style={{ ...IS, paddingRight:44 }} />
            <button onClick={() => setShowPw(s => !s)} style={{ position:"absolute", right:13, top:"50%", transform:"translateY(-50%)", background:"none", border:"none", color:SUB, cursor:"pointer", display:"flex" }}>
              {showPw ? <IEyeOff /> : <IEye />}
            </button>
          </div>
          {errs.pass && <div style={{ color:RED, fontSize:11, marginTop:4 }}>{errs.pass}</div>}
        </div>

        {mode === "register" && (
          <>
            <TInput label="Potwierdź hasło" type="password" value={form.pass2} onChange={sf("pass2")} error={errs.pass2} placeholder="••••••••" />
            <TInput label="Rok urodzenia" type="number" value={form.year} onChange={sf("year")} error={errs.year} placeholder="np. 1985"
              hint={cat ? "Kategoria: " + cat : ""} />
          </>
        )}

        <Btn full onClick={submit} disabled={busy} sx={{ marginTop:6 }}>
          {busy ? "Ładowanie..." : mode === "login" ? "ZALOGUJ SIĘ" : "UTWÓRZ KONTO"}
        </Btn>
      </div>

      <button onClick={onGuest} className="no-tap" style={{ background:"none", border:"1px solid " + BDR, borderRadius:11, padding:"11px 26px", color:SUB, cursor:"pointer", fontSize:12, fontFamily:FT, letterSpacing:1.2, marginBottom:22, textTransform:"uppercase", animation:"fadeUp 0.55s " + SPR + " 0.16s both" }}>
        PRZEGLĄDAJ BEZ LOGOWANIA →
      </button>

    </div>
  );
}

