// ═══════════════════════════════════════════════════════════════
// GPX MAP — leaflet from CDN, dark tiles, red track polyline
// ═══════════════════════════════════════════════════════════════
function GpxMap({ url, gpxText: gpxTextProp, fileName }) {
  const containerRef = useRef(null);
  const [state, setState] = useState({ loading:true, error:null, stats:null });

  useEffect(() => {
    if (!url && !gpxTextProp) return;
    let cancelled = false;
    let map;

    async function loadLeaflet() {
      if (!document.querySelector("link[data-leaflet]")) {
        const link = document.createElement("link");
        link.rel = "stylesheet";
        link.href = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
        link.setAttribute("data-leaflet", "1");
        document.head.appendChild(link);
      }
      if (!window.L) {
        await new Promise((res, rej) => {
          const s = document.createElement("script");
          s.src = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
          s.onload = res;
          s.onerror = () => rej(new Error("Nie udało się załadować biblioteki mapy"));
          document.head.appendChild(s);
        });
      }
      return window.L;
    }

    function parseAndRender(L, txt) {
      const doc = new DOMParser().parseFromString(txt, "application/xml");
      if (doc.querySelector("parsererror")) throw new Error("Nieprawidłowy plik XML");

      const trkpts = Array.from(doc.querySelectorAll("trkpt, rtept, wpt"));
      const pts = trkpts.map(p => [
        parseFloat(p.getAttribute("lat")),
        parseFloat(p.getAttribute("lon")),
      ]).filter(([a, b]) => !isNaN(a) && !isNaN(b));

      if (pts.length < 2) throw new Error("Brak punktów GPS w pliku");

      const eles = trkpts.map(p => {
        const e = p.querySelector("ele");
        return e ? parseFloat(e.textContent) : null;
      }).filter(v => v !== null && !isNaN(v));

      let dist = 0;
      for (let i = 1; i < pts.length; i++) {
        const [la1, lo1] = pts[i - 1];
        const [la2, lo2] = pts[i];
        const R = 6371;
        const dLa = (la2 - la1) * Math.PI / 180;
        const dLo = (lo2 - lo1) * Math.PI / 180;
        const a = Math.sin(dLa / 2) ** 2 + Math.cos(la1 * Math.PI / 180) * Math.cos(la2 * Math.PI / 180) * Math.sin(dLo / 2) ** 2;
        dist += R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
      }

      let elevGain = 0;
      for (let i = 1; i < eles.length; i++) {
        const d = eles[i] - eles[i - 1];
        if (d > 0) elevGain += d;
      }

      if (!containerRef.current) return;

      map = L.map(containerRef.current, { zoomControl:true, scrollWheelZoom:false, attributionControl:false });

      L.tileLayer("https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png", {
        maxZoom:19, subdomains:"abcd",
      }).addTo(map);

      const line = L.polyline(pts, { color:"#D0000E", weight:5, opacity:1, lineCap:"round", lineJoin:"round" }).addTo(map);

      const startIcon = L.divIcon({ html:'<div style="width:14px;height:14px;border-radius:50%;background:#34C759;border:2px solid #fff;box-shadow:0 0 10px rgba(52,199,89,0.8);"></div>', className:"", iconSize:[14,14], iconAnchor:[7,7] });
      const endIcon   = L.divIcon({ html:'<div style="width:14px;height:14px;border-radius:50%;background:#FF0026;border:2px solid #fff;box-shadow:0 0 12px rgba(255,0,38,0.9);"></div>', className:"", iconSize:[14,14], iconAnchor:[7,7] });
      L.marker(pts[0], { icon:startIcon }).addTo(map);
      L.marker(pts[pts.length - 1], { icon:endIcon }).addTo(map);
      map.fitBounds(line.getBounds(), { padding:[22,22] });

      setState({ loading:false, error:null, stats:{ points:pts.length, dist:dist.toFixed(1), elev:elevGain > 0 ? Math.round(elevGain) : null } });
    }

    async function init() {
      try {
        setState({ loading:true, error:null, stats:null });
        const L = await loadLeaflet();
        if (cancelled) return;

        let txt;
        if (gpxTextProp) {
          txt = gpxTextProp;
        } else {
          const r = await fetch(url);
          if (!r.ok) throw new Error("HTTP " + r.status);
          txt = await r.text();
        }
        if (cancelled) return;
        parseAndRender(L, txt);
      } catch (e) {
        if (!cancelled) setState({ loading:false, error:e.message || "Błąd ładowania", stats:null });
      }
    }

    init();
    return () => {
      cancelled = true;
      if (map) { try { map.remove(); } catch(_){} }
    };
  }, [url, gpxTextProp]);

  if (!url && !gpxTextProp) return null;

  const downloadHref = gpxTextProp
    ? "data:application/gpx+xml;charset=utf-8," + encodeURIComponent(gpxTextProp)
    : url;
  const downloadName = fileName || "trasa.gpx";

  return (
    <div style={{ marginBottom:14, borderRadius:14, overflow:"hidden", border:"1px solid " + BDR, background:SURF, boxShadow:"0 1px 0 rgba(255,255,255,0.04) inset, 0 8px 24px rgba(0,0,0,0.40)" }}>
      <div style={{ padding:"12px 16px 9px", display:"flex", justifyContent:"space-between", alignItems:"center", gap:9 }}>
        <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2.2, textTransform:"uppercase", fontWeight:600 }}>TRASA GPX</div>
        <div style={{ display:"flex", gap:10, alignItems:"center" }}>
          {state.stats && (
            <div style={{ display:"flex", gap:8, fontFamily:FT, fontSize:11, fontWeight:600, letterSpacing:0.4 }}>
              <span style={{ color:RED }}>{state.stats.dist} km</span>
              {state.stats.elev !== null && <span style={{ color:SUB }}>· ⛰ {state.stats.elev} m</span>}
              <span style={{ color:MUTED }}>· {state.stats.points} pkt</span>
            </div>
          )}
          {gpxTextProp && (
            <a href={downloadHref} download={downloadName}
              style={{ color:RED, textDecoration:"none", fontFamily:FT, fontWeight:700, fontSize:10, letterSpacing:1, padding:"4px 10px", background:REDD, border:"1px solid " + REDB, borderRadius:7, whiteSpace:"nowrap" }}>
              ⬇ POBIERZ
            </a>
          )}
        </div>
      </div>
      <div ref={containerRef} style={{ height:260, background:"#e8e8ea", position:"relative" }}>
        {state.loading && (
          <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:10, zIndex:1 }}>
            <div style={{ display:"flex", gap:6 }}>
              <div style={{ width:8, height:8, borderRadius:"50%", background:RED, animation:"dot1 1.2s ease-in-out infinite", boxShadow:"0 0 10px " + REDG }} />
              <div style={{ width:8, height:8, borderRadius:"50%", background:RED, animation:"dot2 1.2s ease-in-out 0.2s infinite", boxShadow:"0 0 10px " + REDG }} />
              <div style={{ width:8, height:8, borderRadius:"50%", background:RED, animation:"dot3 1.2s ease-in-out 0.4s infinite", boxShadow:"0 0 10px " + REDG }} />
            </div>
            <div style={{ fontSize:10, color:SUB, fontFamily:FT, letterSpacing:1.4, textTransform:"uppercase", fontWeight:600 }}>Ładuję trasę...</div>
          </div>
        )}
        {state.error && (
          <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", flexDirection:"column", gap:7, padding:18, textAlign:"center", zIndex:1 }}>
            <div style={{ fontSize:26, opacity:0.7 }}>⚠</div>
            <div style={{ fontSize:12, color:RED, fontFamily:FT, fontWeight:700, letterSpacing:1, textTransform:"uppercase" }}>BŁĄD WCZYTANIA TRASY</div>
            <div style={{ fontSize:11, color:MUTED, lineHeight:1.5, maxWidth:280 }}>{state.error}</div>
            {url && <a href={url} target="_blank" rel="noreferrer" style={{ fontSize:11, color:RED, marginTop:6, textDecoration:"none", fontFamily:FT, fontWeight:600, letterSpacing:0.6 }}>OTWÓRZ GPX W NOWEJ KARCIE →</a>}
          </div>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// RIDES SCREEN
// ═══════════════════════════════════════════════════════════════
function RidesScreen({ data, setData, currentUser, toast, rsvpRide, addPhotos, deletePhoto }) {
  const [detail, setDetail] = useState(null);
  const [editing, setEditing] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [sending, setSending] = useState(null);
  const gpxRef = useRef();
  const imgRef = useRef();
  const isAdmin = currentUser && currentUser.role === "admin";

  const emptyForm = { title:"", date:"", time:"07:00", km:"", elev:"", avg:"", desc:"", gpx:null, gpxText:null, gpxUrl:"", img:null, meet:"", status:"upcoming" };
  const [form, setForm] = useState(emptyForm);
  const sf = k => e => setForm(f => ({ ...f, [k]: e.target.value }));

  function openAdd() { setForm(emptyForm); setEditing(null); setShowForm(true); }

  function openEdit(r) {
    setForm({ ...r, km: String(r.km), elev: String(r.elev) });
    setEditing(r);
    setDetail(null);
    setShowForm(true);
  }

  function generateCoverImage(title) {
    try {
      const canvas = document.createElement("canvas");
      canvas.width  = 800;
      canvas.height = 400;
      const ctx = canvas.getContext("2d");
      const wolfImg = new Image();
      wolfImg.src = WOLF_BG;
      wolfImg.onload = () => {};
      ctx.drawImage(wolfImg, 0, 0, 800, 400);
      ctx.fillStyle = "rgba(0,0,0,0.55)";
      ctx.fillRect(0, 0, 800, 400);
      ctx.fillStyle = RED;
      ctx.fillRect(0, 300, 800, 6);
      ctx.fillStyle = "#ffffff";
      ctx.font = "bold 52px 'Oswald', sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(title.toUpperCase(), 400, 200);
      ctx.fillStyle = RED;
      ctx.font = "600 28px 'Oswald', sans-serif";
      ctx.fillText("WATAHA MILICZ · COFFEE RIDE", 400, 260);
      return canvas.toDataURL("image/jpeg", 0.85);
    } catch(e) {
      return WOLF_BG;
    }
  }

  async function save() {
    if (!form.title || !form.date) return;
    const isUpcoming = new Date(form.date) > new Date();
    const rideNum    = nextRideId();
    const rideId     = "CR-" + new Date().getFullYear() + "-" + String(rideNum).padStart(3, "0");
    let coverImg = form.img || WOLF_BG;
    // Wgraj zdjęcie do Storage jeśli to base64
    if (form.img && form.img.startsWith("data:")) {
      try { coverImg = await b64ToStorage("ride-images", `${rideId}/cover.jpg`, form.img); }
      catch(e) { coverImg = WOLF_BG; }
    }
    if (editing) {
      let editImg = form.img;
      if (form.img && form.img.startsWith("data:")) {
        try { editImg = await b64ToStorage("ride-images", `${editing.id}/cover.jpg`, form.img); } catch(e) {}
      }
      const updated = { ...editing, ...form, img: editImg || editing.img, km:+form.km||0, elev:+form.elev||0 };
      setData(d => ({ ...d, rides: d.rides.map(r => r.id === editing.id ? updated : r) }));
      await sb.from("rides").update(rideToDB(updated)).eq("id", editing.id);
      toast("Ustawka zaktualizowana!");
      setEditing(null);
    } else {
      const nr = { ...form, id: rideId, rideNum, km:+form.km||0, elev:+form.elev||0, status: isUpcoming ? "upcoming" : "done", sent:false, img: coverImg };
      setData(d => {
        const notif = { id:"n"+Date.now(), type:"ride", title:"Nowy Coffee Ride!", body:nr.title+" ("+rideId+") — "+nr.date+" godz. "+nr.time, time:"teraz", read:false };
        return { ...d, rides:[nr, ...d.rides], notifs:[notif, ...d.notifs] };
      });
      await sb.from("rides").insert(rideToDB(nr));
      await sb.from("notifications").insert({ id:"n"+Date.now(), type:"ride", title:"Nowy Coffee Ride!", body:nr.title+" ("+rideId+") — "+nr.date+" godz. "+nr.time, time_label:"teraz", read_by:[] });

      // Webhook do Make.com — automatyzacja posta na FB + grafika
      if (data.site.webhookUrl) {
        fetch(data.site.webhookUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            type:    "new_coffee_ride",
            id:      rideId,
            title:   nr.title,
            date:    nr.date,
            time:    nr.time,
            km:      nr.km,
            elev:    nr.elev,
            avg:     nr.avg,
            meet:    nr.meet,
            desc:    nr.desc,
            // Gotowy tekst posta na Facebook
            fb_text: `☕ ${nr.title}\n\n📅 ${nr.date} godz. ${nr.time}\n📍 Zbiórka: ${nr.meet}\n🚴 Dystans: ${nr.km} km | Przewyższenie: ${nr.elev} m | Tempo: ${nr.avg} km/h\n\n${nr.desc || ""}\n\n#WatahaMilicz #CoffeeRide #Kolarstwo #MiliczBikeCollective`,
          }),
        }).catch(e => console.warn("Webhook ride:", e));
      }

      toast("Coffee Ride " + rideId + " dodany!");
    }
    setShowForm(false);
    setForm(emptyForm);
  }

  async function delRide(id) {
    setData(d => ({ ...d, rides: d.rides.filter(r => r.id !== id) }));
    await sb.from("rides").delete().eq("id", id);
    setDetail(null); toast("Ustawka usunięta");
  }

  async function sendWH(r) {
    if (!data.site.webhookUrl) { toast("Brak URL webhooka w ustawieniach", "error"); return; }
    setSending(r.id);
    try {
      await fetch(data.site.webhookUrl, {
        method:"POST",
        headers:{ "Content-Type":"application/json" },
        body: JSON.stringify({ id:r.id, rideNum:r.rideNum, title:r.title, date:r.date, time:r.time, km:r.km, elev:r.elev, avg:r.avg, desc:r.desc, gpx:r.gpx, gpxUrl:r.gpxUrl, meet:r.meet, club:data.site.clubName }),
      }).catch(() => {});
      setData(d => ({ ...d, rides: d.rides.map(x => x.id === r.id ? { ...x, sent:true } : x) }));
      toast("Webhook wysłany do Make.com!");
    } catch (e) {
      toast("Błąd wysyłki", "error");
    }
    setSending(null);
  }

  const today = new Date().toISOString().slice(0,10);
  // Auto-status: jeśli data minęła, traktuj jako zakończone
  const ridesWithStatus = data.rides.map(r => ({ ...r, effectiveStatus: r.status === "upcoming" && r.date < today ? "done" : r.status }));
  const upcoming = ridesWithStatus.filter(r => r.effectiveStatus === "upcoming").sort((a,b) => a.date.localeCompare(b.date));
  const done     = ridesWithStatus.filter(r => r.effectiveStatus === "done").sort((a,b) => b.date.localeCompare(a.date));

  function RideRow({ r }) {
    const img = r.img || WOLF_BG;
    return (
      <div onClick={() => setDetail(r)} className="card-hover no-tap" style={{
        background:SURF, backgroundImage: r.status === "upcoming" ? CARD_GRAD_RED : CARD_GRAD,
        borderRadius:14, border:"1px solid " + (r.status === "upcoming" ? REDB : BDR),
        padding:"14px 16px", marginBottom:11, cursor:"pointer", display:"flex", gap:13, alignItems:"center",
        boxShadow:"0 1px 0 rgba(255,255,255,0.04) inset, 0 8px 24px rgba(0,0,0,0.40)",
      }}>
        <div style={{ width:60, height:60, borderRadius:10, overflow:"hidden", flexShrink:0, position:"relative", boxShadow: r.status === "upcoming" ? "0 0 16px " + REDG : "none" }}>
          <img src={img} alt="" style={{ width:"100%", height:"100%", objectFit:"cover" }} />
          {r.status === "upcoming" && <div style={{ position:"absolute", inset:0, background:"linear-gradient(135deg, rgba(255,0,38,0.18) 0%, transparent 100%)" }} />}
        </div>
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ display:"flex", gap:6, alignItems:"center", marginBottom:5, flexWrap:"wrap" }}>
            <span style={{ fontFamily:FT, fontSize:15, fontWeight:700, letterSpacing:0.5, textTransform:"uppercase" }}>{r.title}</span>
            {r.status === "upcoming" && <Pill label="NADCHODZI" />}
            {r.sent && <Pill label="FB✓" color={GRN} />}
          </div>
          <div style={{ display:"flex", gap:6, alignItems:"center", marginBottom:3 }}>
            {r.id && r.id.startsWith("CR-") && <Pill label={r.id} color={MUTED} sz={9} />}
          </div>
          <div style={{ color:SUB, fontSize:12, display:"flex", gap:12, flexWrap:"wrap" }}>
            <span>📅 {r.date}</span>
            <span>📏 {r.km} km</span>
            <span>⛰ {r.elev} m</span>
          </div>
        </div>
        <div style={{ color:MUTED, flexShrink:0 }}><IChevR /></div>
      </div>
    );
  }


  return (
    <div className="fade-stagger">
      <SHead title="COFFEE RIDES" sub="Nasze wspólne ustawki"
        action={isAdmin && <Btn size="sm" onClick={openAdd}><IPlus /> DODAJ</Btn>}
      />
      {upcoming.length > 0 && (
        <>
          <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2.4, marginBottom:11, textTransform:"uppercase" }}>NADCHODZĄCE</div>
          {upcoming.map(r => <RideRow key={r.id} r={r} />)}
          <div style={{ height:1, background:BDR, margin:"18px 0" }} />
          <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2.4, marginBottom:11, textTransform:"uppercase" }}>ZAKOŃCZONE</div>
        </>
      )}
      {done.map(r => <RideRow key={r.id} r={r} />)}

      {showForm && (
        <Sheet title={editing ? "EDYTUJ USTAWKĘ" : "NOWA USTAWKA"} onClose={() => { setShowForm(false); setEditing(null); }}>
          <TInput label="Nazwa ustawki" value={form.title} onChange={sf("title")} placeholder="Coffee Ride #14" />
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:11 }}>
            <TInput label="Data" type="date" value={form.date} onChange={sf("date")} />
            <TInput label="Godzina" type="time" value={form.time} onChange={sf("time")} />
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:11 }}>
            <TInput label="km" type="number" value={form.km} onChange={sf("km")} placeholder="65" />
            <TInput label="Przewyz. m" type="number" value={form.elev} onChange={sf("elev")} placeholder="400" />
            <TInput label="Tempo km/h" value={form.avg} onChange={sf("avg")} placeholder="22-26" />
          </div>
          <TInput label="Miejsce startu" value={form.meet} onChange={sf("meet")} placeholder="Plac Wolności, Milicz" />
          <TArea label="Opis trasy (FB)" value={form.desc} onChange={sf("desc")} placeholder="Opisz trasę..." />
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:11, marginBottom:6 }}>
            <div>
              <input ref={gpxRef} type="file" accept=".gpx" onChange={e => { const f = e.target.files[0]; if (!f) return; const rr = new FileReader(); rr.onload = ev => setForm(x => ({ ...x, gpx:f.name, gpxText:ev.target.result })); rr.readAsText(f); }} style={{ display:"none" }} />
              <Btn size="sm" v="ghost" sx={{ width:"100%" }} onClick={() => gpxRef.current.click()}><IMap /> GPX</Btn>
              {form.gpx && <div style={{ color:GRN, fontSize:11, marginTop:5, textAlign:"center" }}>✓ {form.gpx}</div>}
            </div>
            <div>
              <input ref={imgRef} type="file" accept="image/*" onChange={e => { const f = e.target.files[0]; if (!f) return; const rr = new FileReader(); rr.onload = ev => setForm(x => ({ ...x, img: ev.target.result })); rr.readAsDataURL(f); }} style={{ display:"none" }} />
              <Btn size="sm" v="ghost" sx={{ width:"100%" }} onClick={() => imgRef.current.click()}><IPhoto /> GRAFIKA</Btn>
              {form.img && <div style={{ color:GRN, fontSize:11, marginTop:5, textAlign:"center" }}>✓ Dodano</div>}
            </div>
          </div>
          {form.img && <img src={form.img} alt="" style={{ width:"100%", borderRadius:11, maxHeight:140, objectFit:"cover", marginBottom:12 }} />}
          <TInput label="LINK DO PLIKU GPX (URL)" value={form.gpxUrl} onChange={sf("gpxUrl")} placeholder="https://..../trasa.gpx"
            hint="Wklej bezposredni link do pliku .gpx — mapa wyswietli sie w szczegolach. Host musi miec wlaczone CORS (np. GitHub raw, Dropbox direct, wlasny serwer)." />
          <div style={{ display:"flex", gap:11, marginTop:10 }}>
            <Btn full onClick={save}>{editing ? "ZAPISZ ZMIANY" : "DODAJ USTAWKĘ"}</Btn>
            <Btn full v="ghost" onClick={() => { setShowForm(false); setEditing(null); }}>ANULUJ</Btn>
          </div>
        </Sheet>
      )}

      {detail && (
        <DetailSheet
          heroImage={detail.img || WOLF_BG}
          title={detail.title}
          badges={<>
            {detail.status === "upcoming" && <Pill label="NADCHODZI" />}
            {detail.id && detail.id.startsWith("CR-") && <Pill label={detail.id} color={MUTED} sz={9} />}
            {detail.sent && <Pill label="FB✓" color={GRN} />}
          </>}
          onClose={() => setDetail(null)}
        >
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:9, marginBottom:18 }}>
            {[["📏","km",detail.km],["⛰","m",detail.elev],["⚡","km/h",detail.avg]].map(([ic,unit,val]) => (
              <Card hover={false} key={unit} sx={{ padding:"14px 8px", textAlign:"center" }}>
                <div style={{ fontSize:20, marginBottom:5 }}>{ic}</div>
                <div style={{ fontFamily:FT, fontSize:22, fontWeight:700, color:RED, lineHeight:1, letterSpacing:0.5 }}>
                  {typeof val === "number" ? <CountUp value={val} /> : val}
                </div>
                <div style={{ fontSize:10, color:MUTED, marginTop:4, fontFamily:FT, letterSpacing:1 }}>{unit}</div>
              </Card>
            ))}
          </div>
          <Card sx={{ padding:"14px 16px", marginBottom:14 }}>
            <div style={{ color:SUB, fontSize:13, display:"flex", flexDirection:"column", gap:6 }}>
              <span>📅 {detail.date} · {detail.time}</span>
              {detail.meet && <span>📍 {detail.meet}</span>}
            </div>
          </Card>
          {detail.desc && (
            <Card sx={{ padding:"14px 16px", marginBottom:14 }}>
              <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2.2, marginBottom:8, textTransform:"uppercase" }}>OPIS TRASY</div>
              <p style={{ color:TEXT, fontSize:13, lineHeight:1.7, margin:0 }}>{detail.desc}</p>
            </Card>
          )}
          <RsvpBtn itemId={detail.id} user={currentUser} attendees={detail.attendees} onToggle={rsvpRide} />
          {detail.gpxUrl && <GpxMap url={detail.gpxUrl} />}
          {detail.gpxText && !detail.gpxUrl && <GpxMap gpxText={detail.gpxText} fileName={detail.gpx} />}
          <GalleryGrid photos={detail.photos} isAdmin={isAdmin}
            onAdd={e => addPhotos("ride", detail.id, e.target.files)}
            onDelete={p => deletePhoto("ride", detail.id, p)} />
          {detail.status === "done" && detail.attendees?.filter(a=>a.status==="going").length > 0 && (
            <div style={{ background:SURF, borderRadius:13, padding:"14px 16px", marginBottom:14, border:"1px solid "+BDR }}>
              <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2, textTransform:"uppercase", marginBottom:10, fontWeight:600 }}>
                UCZESTNICY ({detail.attendees.filter(a=>a.status==="going").length})
              </div>
              <div style={{ display:"flex", flexWrap:"wrap", gap:8 }}>
                {detail.attendees.filter(a=>a.status==="going").map(a => (
                  <div key={a.user_id} style={{ display:"flex", alignItems:"center", gap:7, background:SURF2, borderRadius:20, padding:"4px 11px 4px 4px" }}>
                    <Avatar user={{ name:a.profiles?.name||"?", avatar:a.profiles?.avatar_url }} size={22} />
                    <span style={{ fontSize:11, color:TEXT }}>{a.profiles?.name||"Zawodnik"}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
          {detail.gpx && !detail.gpxUrl && !detail.gpxText && (
            <div style={{ background:SURF2, borderRadius:11, padding:"11px 15px", display:"flex", alignItems:"center", gap:10, color:SUB, fontSize:12, marginBottom:14, border:"1px solid " + BDR }}>
              <IMap />
              <span style={{ flex:1 }}>GPX: {detail.gpx}</span>
              <span style={{ color:MUTED, fontSize:10 }}>brak pliku</span>
            </div>
          )}
          {isAdmin && (
            <div style={{ display:"flex", gap:8, paddingTop:14, borderTop:"1px solid " + BDR }}>
              <Btn size="sm" v={detail.sent ? "success" : "ghost"} onClick={() => sendWH(detail)} disabled={sending === detail.id || detail.sent}>
                <ISend />{detail.sent ? "Wysłano FB" : sending === detail.id ? "Wysyłam..." : "Wyślij na FB"}
              </Btn>
              <Btn size="sm" v="ghost" onClick={() => openEdit(detail)}><IEdit /> Edytuj</Btn>
              <Btn size="sm" v="danger" sx={{ marginLeft:"auto" }} onClick={() => delRide(detail.id)}><ITrash /></Btn>
            </div>
          )}
        </DetailSheet>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// RACES SCREEN
// ═══════════════════════════════════════════════════════════════
function RacesScreen({ data, setData, currentUser, toast, rsvpRace }) {
  const [showForm,  setShowForm]  = useState(false);
  const [editRace,  setEditRace]  = useState(null);
  const [resRaceId, setResRaceId] = useState(null);
  const [editResIdx,setEditResIdx]= useState(null);
  const [exp, setExp] = useState({});
  const logoRef = useRef();
  const isAdmin = currentUser && currentUser.role === "admin";

  const emptyR = { name:"", sub:"", date:"", loc:"", logo:null, dists:[{ lbl:"Dystans glowny", km:"" }] };
  const [form, setForm] = useState(emptyR);
  const sf = k => e => setForm(f => ({ ...f, [k]: e.target.value }));

  const emptyRes = { uid:"", name:"", cat:"", dist:"", place:"", medal:"none" };
  const [resForm, setResForm] = useState(emptyRes);
  const srf = k => e => setResForm(f => ({ ...f, [k]: e.target.value }));

  function addDist()        { setForm(f => ({ ...f, dists:[...f.dists, { lbl:"", km:"" }] })); }
  function updDist(i, k, v) { setForm(f => ({ ...f, dists: f.dists.map((d, idx) => idx === i ? { ...d, [k]:v } : d) })); }
  function delDist(i)       { setForm(f => ({ ...f, dists: f.dists.filter((_, idx) => idx !== i) })); }

  async function saveRace() {
    if (!form.name || !form.date) return;
    let logo = form.logo;
    if (logo && logo.startsWith("data:")) {
      const raceId = editRace ? editRace.id : "rc" + Date.now();
      try { logo = await b64ToStorage("race-logos", `${raceId}/logo.jpg`, logo); } catch(e) {}
    }
    const cleaned = { ...form, logo, dists: form.dists.map(d => ({ ...d, km:+d.km || 0 })) };
    if (editRace) {
      setData(d => ({ ...d, races: d.races.map(r => r.id === editRace.id ? { ...r, ...cleaned } : r) }));
      await sb.from("races").update(raceToDB(cleaned)).eq("id", editRace.id);
      toast("Start zaktualizowany!"); setEditRace(null);
    } else {
      const nr = { ...cleaned, id:"rc"+Date.now(), status: new Date(form.date) > new Date() ? "upcoming" : "done", results:[] };
      setData(d => {
        const notif = { id:"n"+Date.now(), type:"race", title:"Nowy start w kalendarzu!", body:nr.name+" — "+nr.date+", "+nr.loc, time:"teraz", read:false };
        return { ...d, races:[nr, ...d.races], notifs:[notif, ...d.notifs] };
      });
      await sb.from("races").insert(raceToDB(nr));
      await sb.from("notifications").insert({ id:"n"+Date.now(), type:"race", title:"Nowy start w kalendarzu!", body:nr.name+" — "+nr.date+", "+nr.loc, time_label:"teraz", read_by:[] });
      toast("Start dodany!");
    }
    setShowForm(false); setForm(emptyR);
  }

  async function saveResult(raceId) {
    if (!resForm.name) return;
    const res = { ...resForm, medal: resForm.medal === "none" ? null : resForm.medal, place:+resForm.place || null };
    if (editResIdx !== null) {
      const existing = data.races.find(r => r.id === raceId)?.results[editResIdx];
      setData(d => ({ ...d, races: d.races.map(r => r.id === raceId ? { ...r, results: r.results.map((x, i) => i === editResIdx ? res : x) } : r) }));
      if (existing?._rid) await sb.from("race_results").update({ uid:res.uid||"", name:res.name, cat:res.cat, dist:res.dist, place:res.place, medal:res.medal }).eq("id", existing._rid);
      toast("Wynik zaktualizowany!");
    } else {
      setData(d => ({ ...d, races: d.races.map(r => r.id === raceId ? { ...r, results:[...r.results, res] } : r) }));
      await sb.from("race_results").insert({ race_id:raceId, uid:res.uid||"", name:res.name, cat:res.cat||"", dist:res.dist||"", place:res.place, medal:res.medal });
      toast("Wynik dodany!");
    }
    setResRaceId(null);
    setEditResIdx(null);
    setResForm(emptyRes);
  }

  async function delRace(id) {
    setData(d => ({ ...d, races: d.races.filter(r => r.id !== id) }));
    await sb.from("race_results").delete().eq("race_id", id);
    await sb.from("races").delete().eq("id", id);
    toast("Start usunięty");
  }

  async function toggleRaceStatus(r) {
    const newStatus = (r.effectiveStatus || r.status) === "upcoming" ? "done" : "upcoming";
    setData(d => ({ ...d, races: d.races.map(x => x.id === r.id ? { ...x, status: newStatus } : x) }));
    await sb.from("races").update({ status: newStatus }).eq("id", r.id);
    toast(newStatus === "done" ? "Przeniesiono do zakończonych" : "Przeniesiono do nadchodzących");
  }

  async function delResult(raceId, idx) {
    const existing = data.races.find(r => r.id === raceId)?.results[idx];
    setData(d => ({ ...d, races: d.races.map(r => r.id === raceId ? { ...r, results: r.results.filter((_, i) => i !== idx) } : r) }));
    if (existing?._rid) await sb.from("race_results").delete().eq("id", existing._rid);
    toast("Wynik usunięty");
  }

  const MED = { gold:"🥇", silver:"🥈", bronze:"🥉" };
  const todayR = new Date().toISOString().slice(0,10);
  const racesWithStatus = data.races.map(r => ({ ...r, effectiveStatus: r.status === "upcoming" && r.date < todayR ? "done" : r.status }));
  const upcoming = racesWithStatus.filter(r => r.effectiveStatus === "upcoming").sort((a,b) => a.date.localeCompare(b.date));
  const done     = racesWithStatus.filter(r => r.effectiveStatus === "done").sort((a,b) => b.date.localeCompare(a.date));

  function RaceCard({ r }) {
    const es = r.effectiveStatus || r.status;
    return (
      <Card accent={es === "upcoming"} sx={{ marginBottom:13 }}>
        {es === "upcoming" && (
          <div style={{ height:96, background:HERO_GRAD, display:"flex", alignItems:"center", justifyContent:"center", gap:14, position:"relative", overflow:"hidden" }}>
            <div style={{ position:"absolute", inset:0, background:"radial-gradient(ellipse at center, rgba(255,0,38,0.18) 0%, transparent 70%)" }} />
            {r.logo
              ? <img src={r.logo} alt="" style={{ width:60, height:60, borderRadius:12, objectFit:"cover", border:"2px solid " + REDB, boxShadow:"0 0 20px " + REDG, position:"relative" }} />
              : <span style={{ fontSize:34, position:"relative" }}>🏁</span>}
            <div style={{ textAlign:"center", position:"relative" }}>
              <div style={{ fontFamily:FT, fontWeight:700, fontSize:13, letterSpacing:2, color:TEXT, textTransform:"uppercase" }}>{r.name}</div>
              <div style={{ display:"flex", gap:5, flexWrap:"wrap", justifyContent:"center", marginTop:6 }}>
                {(r.dists || []).map(d => <Pill key={d.lbl} label={d.lbl + " " + d.km + "km"} color={RED} sz={9} />)}
              </div>
            </div>
          </div>
        )}
        <div style={{ padding:"14px 16px" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:7, gap:11 }}>
            {r.status !== "upcoming" && r.logo && (
              <img src={r.logo} alt="" style={{ width:46, height:46, borderRadius:10, objectFit:"cover", flexShrink:0, border:"1px solid " + BDR }} />
            )}
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ fontFamily:FT, fontSize:16, fontWeight:700, letterSpacing:0.6, textTransform:"uppercase" }}>{r.name}</div>
              {r.sub && <div style={{ color:SUB, fontSize:12, marginTop:1 }}>{r.sub}</div>}
            </div>
            <div style={{ display:"flex", gap:6, alignItems:"center", flexShrink:0, marginLeft:8 }}>
              {es === "upcoming" && <Pill label="Nadchodzi" />}
              <RsvpBtn itemId={r.id} user={currentUser} attendees={r.registrations} onToggle={rsvpRace} />
              {isAdmin && (
                <div style={{ display:"flex", gap:5 }}>
                  <button onClick={() => toggleRaceStatus(r)} title={es === "upcoming" ? "Zakończ" : "Przywróć"}
                    style={{ background:es==="upcoming"?REDD:SURF2, border:"1px solid "+(es==="upcoming"?REDB:BDR), color:es==="upcoming"?RED:SUB, borderRadius:7, padding:"5px 8px", cursor:"pointer", fontSize:10, fontFamily:FT, fontWeight:700, letterSpacing:0.5 }}>
                    {es === "upcoming" ? "✓ ZAKOŃCZ" : "↩ WRÓĆ"}
                  </button>
                  <button onClick={() => { setForm({ ...r, dists: r.dists || [{ lbl:"", km:"" }] }); setEditRace(r); setShowForm(true); }}
                    style={{ background:SURF2, border:"1px solid " + BDR, color:SUB, borderRadius:7, padding:"5px 8px", cursor:"pointer", display:"flex" }}>
                    <IEdit />
                  </button>
                  <button onClick={() => { if(window.confirm("Usunąć ten start?")) delRace(r.id); }}
                    style={{ background:REDD, border:"1px solid " + REDB, color:RED, borderRadius:7, padding:"5px 8px", cursor:"pointer", display:"flex" }}>
                    <ITrash />
                  </button>
                </div>
              )}
            </div>
          </div>
          <div style={{ display:"flex", gap:14, color:SUB, fontSize:12, flexWrap:"wrap", marginBottom:7 }}>
            {r.date && <span>📅 {r.date}</span>}
            {r.loc  && <span>📍 {r.loc}</span>}
          </div>
          {r.status !== "upcoming" && (r.dists || []).length > 0 && (
            <div style={{ display:"flex", gap:6, flexWrap:"wrap", marginBottom:9 }}>
              {r.dists.map(d => <Pill key={d.lbl} label={d.lbl + ": " + d.km + "km"} color={MUTED} sz={9} />)}
            </div>
          )}

          {(r.results || []).length > 0 && (
            <>
              <button onClick={() => setExp(e => ({ ...e, [r.id]:!e[r.id] }))}
                style={{ background:"none", border:"none", color:RED, cursor:"pointer", fontSize:12, fontFamily:FT, letterSpacing:0.6, display:"flex", alignItems:"center", gap:5, padding:0, marginBottom:7, textTransform:"uppercase", fontWeight:600 }}>
                <span style={{ display:"flex", transform: exp[r.id] ? "rotate(180deg)" : "none", transition:"transform 0.3s " + SPR }}><IChevD /></span>
                {exp[r.id] ? "Ukryj wyniki" : "Wyniki (" + r.results.length + ")"}
              </button>
              {exp[r.id] && r.results.map((res, i) => {
                const u = res.uid ? data.users.find(x => x.id === res.uid) : null;
                return (
                  <div key={i} style={{ display:"flex", alignItems:"center", gap:11, padding:"9px 0", borderTop:"1px solid " + BDR, animation:"fadeUp 0.3s " + SPR }}>
                    <div style={{ width:34, height:34, borderRadius:"50%", background:SURF2, display:"flex", alignItems:"center", justifyContent:"center", fontSize:17, flexShrink:0, border:"1px solid " + BDR }}>
                      {res.medal ? MED[res.medal] : <span style={{ fontFamily:FT, fontSize:11, color:MUTED, fontWeight:700 }}>{res.place || "–"}</span>}
                    </div>
                    {u && <Avatar user={u} size={32} />}
                    <div style={{ flex:1 }}>
                      <div style={{ fontWeight:600, fontSize:13 }}>{res.name}</div>
                      <div style={{ fontSize:11, color:SUB }}>{res.cat}{res.dist ? " · " + res.dist : ""}</div>
                    </div>
                    {isAdmin && (
                      <div style={{ display:"flex", gap:4 }}>
                        <button onClick={() => { setResForm({ ...res, medal: res.medal || "none", place: String(res.place || ""), uid: res.uid || "" }); setEditResIdx(i); setResRaceId(r.id); }}
                          style={{ background:"none", border:"none", color:SUB, cursor:"pointer", padding:5, display:"flex" }}><IEdit /></button>
                        <button onClick={() => delResult(r.id, i)}
                          style={{ background:"none", border:"none", color:MUTED, cursor:"pointer", padding:5, display:"flex" }}><ITrash /></button>
                      </div>
                    )}
                  </div>
                );
              })}
            </>
          )}
          {isAdmin && (
            <div style={{ marginTop:11, paddingTop:11, borderTop:"1px solid " + BDR }}>
              <Btn size="sm" v="ghost" onClick={() => { setResForm(emptyRes); setEditResIdx(null); setResRaceId(r.id); }}>
                <IPlus /> Dodaj wynik
              </Btn>
            </div>
          )}
        </div>
      </Card>
    );
  }

  return (
    <div className="fade-stagger">
      <SHead title="STARTY ZAWODÓW" sub="Nadchodzące i zakończone wyścigi"
        action={isAdmin && <Btn size="sm" onClick={() => { setForm(emptyR); setEditRace(null); setShowForm(true); }}><IPlus /> DODAJ</Btn>}
      />
      {upcoming.length > 0 && (
        <>
          <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2.4, marginBottom:11, textTransform:"uppercase" }}>NADCHODZĄCE STARTY</div>
          {upcoming.map(r => <RaceCard key={r.id} r={r} />)}
          <div style={{ height:1, background:BDR, margin:"18px 0" }} />
        </>
      )}
      <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2.4, marginBottom:11, textTransform:"uppercase" }}>ZAKOŃCZONE STARTY</div>
      {done.map(r => <RaceCard key={r.id} r={r} />)}

      {showForm && (
        <Sheet title={editRace ? "EDYTUJ START" : "NOWY START"} onClose={() => { setShowForm(false); setEditRace(null); setForm(emptyR); }}>
          <TInput label="Nazwa wyścigu" value={form.name} onChange={sf("name")} placeholder="Maraton Kolarski" />
          <TInput label="Podtytuł / edycja" value={form.sub} onChange={sf("sub")} placeholder="np. Od Świtu do Zmierzchu" />
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:11 }}>
            <TInput label="Data" type="date" value={form.date} onChange={sf("date")} />
            <TInput label="Lokalizacja" value={form.loc} onChange={sf("loc")} placeholder="Koźmin Wlkp." />
          </div>
          <div style={{ marginBottom:13 }}>
            <label style={{ display:"block", marginBottom:6, fontSize:10, color:SUB, textTransform:"uppercase", letterSpacing:1.6, fontFamily:FT, fontWeight:600 }}>LOGO ZAWODOW</label>
            <input ref={logoRef} type="file" accept="image/*" onChange={e => { const f = e.target.files[0]; if (!f) return; const rr = new FileReader(); rr.onload = ev => setForm(x => ({ ...x, logo: ev.target.result })); rr.readAsDataURL(f); }} style={{ display:"none" }} />
            <div style={{ display:"flex", gap:11, alignItems:"center" }}>
              <Btn size="sm" v="ghost" onClick={() => logoRef.current.click()}><IPhoto /> {form.logo ? "Zmien logo" : "Wgraj logo"}</Btn>
              {form.logo && (
                <>
                  <img src={form.logo} alt="" style={{ width:46, height:46, borderRadius:10, objectFit:"cover", border:"1px solid " + REDB }} />
                  <Btn size="sm" v="danger" onClick={() => setForm(x => ({ ...x, logo:null }))}><ITrash /></Btn>
                </>
              )}
            </div>
          </div>
          <div style={{ marginBottom:13 }}>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:7 }}>
              <label style={{ fontSize:10, color:SUB, textTransform:"uppercase", letterSpacing:1.6, fontFamily:FT, fontWeight:600 }}>DYSTANSE</label>
              <Btn size="sm" v="ghost" onClick={addDist}><IPlus /> Dodaj</Btn>
            </div>
            {form.dists.map((d, i) => (
              <div key={i} style={{ display:"grid", gridTemplateColumns:"1fr 76px auto", gap:8, marginBottom:7, alignItems:"center" }}>
                <input value={d.lbl} onChange={e => updDist(i, "lbl", e.target.value)} placeholder="Nazwa dystansu" style={{ ...IS }} />
                <input type="number" value={d.km} onChange={e => updDist(i, "km", e.target.value)} placeholder="km" style={{ ...IS }} />
                {form.dists.length > 1 && (
                  <button onClick={() => delDist(i)} style={{ background:REDD, border:"1px solid " + REDB, color:RED, borderRadius:9, padding:"10px 11px", cursor:"pointer", display:"flex" }}><ITrash /></button>
                )}
              </div>
            ))}
          </div>
          <div style={{ display:"flex", gap:11 }}>
            <Btn full onClick={saveRace}>{editRace ? "ZAPISZ ZMIANY" : "DODAJ START"}</Btn>
            <Btn full v="ghost" onClick={() => { setShowForm(false); setEditRace(null); setForm(emptyR); }}>ANULUJ</Btn>
          </div>
        </Sheet>
      )}

      {resRaceId && (
        <Sheet title={editResIdx !== null ? "EDYTUJ WYNIK" : "DODAJ WYNIK"} onClose={() => { setResRaceId(null); setResForm(emptyRes); setEditResIdx(null); }}>
          <TSel label="Zawodnik z listy (opcjonalnie)" value={resForm.uid} onChange={e => {
            const u = data.users.find(x => x.id === e.target.value);
            if (u) setResForm(f => ({ ...f, uid:u.id, name:u.name, cat:getCat(u.birthYear) }));
            else   setResForm(f => ({ ...f, uid:"" }));
          }} opts={[{ v:"", l:"— Wpisz ręcznie —" }, ...data.users.filter(u => u.inTeam).map(u => ({ v:u.id, l:u.name + " (" + getCat(u.birthYear) + ")" }))]} />
          <TInput label="Imię i nazwisko" value={resForm.name} onChange={srf("name")} placeholder="lub wpisz ręcznie" />
          <TInput label="Kategoria" value={resForm.cat} onChange={srf("cat")} placeholder="M40, Masters 30+..." />
          <TSel label="Dystans" value={resForm.dist} onChange={srf("dist")}
            opts={[{ v:"", l:"— wybierz —" }, ...(data.races.find(r => r.id === resRaceId)?.dists || []).map(d => ({ v:d.lbl, l:d.lbl + " (" + d.km + "km)" }))]} />
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:11 }}>
            <TInput label="Miejsce" type="number" value={resForm.place} onChange={srf("place")} placeholder="1" />
            <TSel label="Medal" value={resForm.medal} onChange={srf("medal")} opts={[{ v:"none", l:"Brak" },{ v:"gold", l:"🥇 Zloto" },{ v:"silver", l:"🥈 Srebro" },{ v:"bronze", l:"🥉 Braz" }]} />
          </div>
          <div style={{ display:"flex", gap:11 }}>
            <Btn full onClick={() => saveResult(resRaceId)}>{editResIdx !== null ? "ZAPISZ ZMIANY" : "DODAJ WYNIK"}</Btn>
            <Btn full v="ghost" onClick={() => { setResRaceId(null); setResForm(emptyRes); setEditResIdx(null); }}>ANULUJ</Btn>
          </div>
        </Sheet>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// RESULTS SCREEN
// ═══════════════════════════════════════════════════════════════
function ResultsScreen({ data }) {
  const [exp, setExp] = useState({});
  let g = 0, s = 0, b = 0;
  data.races.forEach(r => (r.results || []).forEach(res => {
    if (res.medal === "gold")   g++;
    if (res.medal === "silver") s++;
    if (res.medal === "bronze") b++;
  }));
  const MED = { gold:"🥇", silver:"🥈", bronze:"🥉" };

  return (
    <div className="fade-stagger">
      <SHead title="WYNIKI" sub="Nasze osiągnięcia na zawodach" />
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:11, marginBottom:22 }}>
        {[["🥇","ZLOTO",g,GOLD],["🥈","SREBRO",s,SILV],["🥉","BRAZ",b,BRNZ]].map(([ic,lbl,v,col]) => (
          <Card key={lbl} sx={{ padding:"18px 10px", textAlign:"center", position:"relative", overflow:"hidden" }}>
            <div style={{ position:"absolute", top:-15, right:-15, width:60, height:60, background:"radial-gradient(circle, " + col + "33 0%, transparent 70%)", pointerEvents:"none" }} />
            <div style={{ fontSize:26, marginBottom:7, position:"relative" }}>{ic}</div>
            <div style={{ fontFamily:FT, fontSize:30, fontWeight:700, color:col, lineHeight:1, position:"relative", letterSpacing:0.5 }}>
              <CountUp value={v} />
            </div>
            <div style={{ fontSize:9, color:MUTED, letterSpacing:2.2, marginTop:5, fontFamily:FT, position:"relative", textTransform:"uppercase" }}>{lbl}</div>
          </Card>
        ))}
      </div>

      {data.races.filter(r => (r.results || []).length > 0).map(r => (
        <Card key={r.id} sx={{ marginBottom:13 }}>
          <button onClick={() => setExp(e => ({ ...e, [r.id]:!e[r.id] }))}
            style={{ width:"100%", background:"none", border:"none", padding:"14px 16px", cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center", gap:12, color:TEXT }}>
            {r.logo && <img src={r.logo} alt="" style={{ width:42, height:42, borderRadius:9, objectFit:"cover", flexShrink:0, border:"1px solid " + BDR }} />}
            <div style={{ textAlign:"left", flex:1, minWidth:0 }}>
              <div style={{ fontFamily:FT, fontSize:15, fontWeight:700, letterSpacing:0.6, textTransform:"uppercase" }}>{r.name}</div>
              <div style={{ color:SUB, fontSize:12, marginTop:3, display:"flex", gap:11, flexWrap:"wrap" }}>
                <span>📅 {r.date}</span>
                {r.loc && <span>📍 {r.loc}</span>}
                <span>{(r.results || []).filter(x => x.medal).map(x => MED[x.medal]).join(" ")}</span>
              </div>
            </div>
            <div style={{ display:"flex", alignItems:"center", gap:9, flexShrink:0 }}>
              <span style={{ color:SUB, fontSize:12 }}>{r.results.length}</span>
              <span style={{ color:MUTED, display:"flex", transform: exp[r.id] ? "rotate(180deg)" : "none", transition:"transform 0.3s " + SPR }}><IChevD /></span>
            </div>
          </button>
          {exp[r.id] && r.results.map((res, i) => {
            const u = res.uid ? data.users.find(x => x.id === res.uid) : null;
            return (
              <div key={i} style={{ display:"flex", alignItems:"center", gap:13, padding:"11px 16px", borderTop:"1px solid " + BDR, animation:"fadeUp 0.35s " + SPR }}>
                <div style={{ width:38, height:38, borderRadius:"50%", background:SURF2, display:"flex", alignItems:"center", justifyContent:"center", fontSize:19, flexShrink:0, border:"1px solid " + BDR }}>
                  {res.medal ? MED[res.medal] : <span style={{ fontFamily:FT, fontSize:13, color:MUTED, fontWeight:700 }}>{res.place || "–"}</span>}
                </div>
                {u && <Avatar user={u} size={34} />}
                <div style={{ flex:1 }}>
                  <div style={{ fontWeight:600, fontSize:14 }}>{res.name}</div>
                  <div style={{ fontSize:12, color:SUB }}>{res.cat}{res.dist ? " · " + res.dist : ""}</div>
                </div>
                {res.place && <div style={{ fontFamily:FT, fontSize:22, fontWeight:700, color: res.medal ? GOLD : SUB }}>{res.place}.</div>}
              </div>
            );
          })}
        </Card>
      ))}
      {data.races.filter(r => (r.results || []).length > 0).length === 0 && (
        <div style={{ color:MUTED, textAlign:"center", padding:"36px 0", fontSize:14 }}>Brak wyników do wyświetlenia</div>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// TEAM SCREEN — full-bleed avatar + glow
// ═══════════════════════════════════════════════════════════════
function TeamScreen({ data }) {
  const [sel, setSel] = useState(null);
  const team = data.users.filter(u => u.inTeam);
  const MED = { gold:"🥇", silver:"🥈", bronze:"🥉" };

  return (
    <div className="fade-stagger">
      <SHead title="ZAWODNICY WATAHY" sub="Nasza ekipa" />
      {team.map(u => {
        const med  = userMedals(u.id, data.races);
        const hist = userHistory(u.id, data.races);
        const cat  = getCat(u.birthYear);
        return (
          <div key={u.id} onClick={() => setSel(u)} className="card-hover no-tap" style={{
            background:SURF, backgroundImage:CARD_GRAD,
            borderRadius:16, border:"1px solid " + BDR,
            marginBottom:12, cursor:"pointer", display:"flex",
            alignItems:"stretch", overflow:"hidden", position:"relative",
            boxShadow:"0 1px 0 rgba(255,255,255,0.04) inset, 0 8px 24px rgba(0,0,0,0.40)",
          }}>
            <div style={{ position:"relative", width:96, flexShrink:0, background:"linear-gradient(135deg, rgba(255,0,38,0.15) 0%, rgba(8,8,10,0.4) 100%)", display:"flex", alignItems:"center", justifyContent:"center" }}>
              <div style={{ position:"absolute", inset:0, background:"radial-gradient(circle at 30% 50%, " + REDG + " 0%, transparent 65%)", opacity:0.6 }} />
              <div style={{ position:"relative", zIndex:1 }}>
                <Avatar user={u} size={68} ring glow />
              </div>
            </div>
            <div style={{ flex:1, minWidth:0, padding:"15px 14px 15px 16px", display:"flex", flexDirection:"column", justifyContent:"center" }}>
              <div style={{ fontFamily:FT, fontSize:16, fontWeight:700, letterSpacing:0.6, marginBottom:5, textTransform:"uppercase" }}>{u.name}</div>
              <div style={{ display:"flex", gap:6, alignItems:"center", marginBottom:7, flexWrap:"wrap" }}>
                <Pill label={cat} />
                {med.total > 0 && (
                  <Pill label={(med.gold > 0 ? "🥇" + med.gold + " " : "") + (med.silver > 0 ? "🥈" + med.silver + " " : "") + (med.bronze > 0 ? "🥉" + med.bronze : "")} color={GOLD} sz={10} />
                )}
              </div>
              {hist.slice(0, 2).map((h, i) => (
                <div key={i} style={{ fontSize:11, color:SUB, display:"flex", alignItems:"center", gap:6 }}>
                  <span>{h.medal ? MED[h.medal] : (h.place ? h.place + "." : "–")}</span>
                  <span style={{ overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{h.race} · {(h.date || "").slice(0, 7)}</span>
                </div>
              ))}
            </div>
            <div style={{ color:MUTED, flexShrink:0, alignSelf:"center", paddingRight:14 }}><IChevR /></div>
          </div>
        );
      })}

      {sel && (() => {
        const med  = userMedals(sel.id, data.races);
        const hist = userHistory(sel.id, data.races);
        const cat  = getCat(sel.birthYear);
        return (
          <DetailSheet
            heroImage={sel.avatar}
            heroOverlay={!sel.avatar && (
              <>
                <div style={{ position:"absolute", inset:0, display:"flex", alignItems:"center", justifyContent:"center", opacity:0.05 }}>
                  <WolfPaw size={300} />
                </div>
                <div style={{ position:"absolute", inset:0, background:"radial-gradient(ellipse at 50% 30%, " + REDG + " 0%, transparent 60%)" }} />
                <div style={{ position:"absolute", top:26, left:"50%", transform:"translateX(-50%)", zIndex:2 }}>
                  <Avatar user={sel} size={88} ring glow />
                </div>
              </>
            )}
            title={sel.name}
            badges={<>
              <Pill label={cat} />
              {sel.birthYear && <Pill label={"ur. " + sel.birthYear} color={MUTED} />}
              {sel.role === "admin" && <Pill label="ADMIN" color={GOLD} />}
            </>}
            onClose={() => setSel(null)}
          >
            {med.total > 0 && (
              <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:9, marginBottom:18 }}>
                {[["🥇",med.gold,GOLD],["🥈",med.silver,SILV],["🥉",med.bronze,BRNZ]].map(([ic,v,col], i) => (
                  <Card hover={false} key={i} sx={{ padding:"14px 8px", textAlign:"center", position:"relative", overflow:"hidden" }}>
                    <div style={{ position:"absolute", top:-15, right:-15, width:60, height:60, background:"radial-gradient(circle, " + col + "33 0%, transparent 70%)" }} />
                    <div style={{ fontSize:22, marginBottom:5, position:"relative" }}>{ic}</div>
                    <div style={{ fontFamily:FT, fontSize:24, fontWeight:700, color:col, position:"relative", letterSpacing:0.5 }}>
                      <CountUp value={v} />
                    </div>
                  </Card>
                ))}
              </div>
            )}
            {hist.length > 0 && (
              <Card sx={{ padding:"4px 0", marginBottom:14 }}>
                <div style={{ fontFamily:FT, fontSize:10, color:SUB, letterSpacing:2.2, padding:"14px 16px 9px", textTransform:"uppercase" }}>HISTORIA STARTÓW</div>
                {hist.map((h, i) => (
                  <div key={i} style={{ display:"flex", alignItems:"center", gap:11, padding:"10px 16px", borderTop:"1px solid " + BDR }}>
                    <div style={{ width:34, height:34, borderRadius:"50%", background:SURF2, display:"flex", alignItems:"center", justifyContent:"center", fontSize:17, flexShrink:0, border:"1px solid " + BDR }}>
                      {h.medal ? MED[h.medal] : <span style={{ fontFamily:FT, fontSize:11, color:MUTED, fontWeight:700 }}>{h.place || "–"}</span>}
                    </div>
                    <div>
                      <div style={{ fontSize:13, fontWeight:600 }}>{h.race}</div>
                      <div style={{ fontSize:11, color:SUB }}>{h.dist} · {(h.date || "").slice(0, 7)}</div>
                    </div>
                  </div>
                ))}
              </Card>
            )}
            {hist.length === 0 && <div style={{ color:MUTED, fontSize:13, textAlign:"center", padding:"24px 0" }}>Brak startów w historii</div>}
          </DetailSheet>
        );
      })()}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// SPONSORS SCREEN
// ═══════════════════════════════════════════════════════════════
function SponsorsScreen({ data, setData, currentUser, toast }) {
  const isAdmin = currentUser && currentUser.role === "admin";
  const [showForm, setShowForm] = useState(false);
  const [editSp, setEditSp] = useState(null);
  const [form, setForm] = useState({ name:"", tier:"Silver", logo:"", desc:"", web:"" });
  const sf = k => e => setForm(f => ({ ...f, [k]: e.target.value }));
  const TC = { Platinum:GOLD, Gold:SILV, Silver:BRNZ };

  async function saveSponsor() {
    if (!form.name) return;
    if (editSp) {
      setData(d => ({ ...d, sponsors: d.sponsors.map(s => s.id === editSp.id ? { ...s, ...form } : s) }));
      await sb.from("sponsors").update({ name:form.name, tier:form.tier, logo:form.logo||"", description:form.desc||"", web:form.web||"" }).eq("id", editSp.id);
      toast("Sponsor zaktualizowany!");
    } else {
      const ns = { ...form, id:"s" + Date.now() };
      setData(d => ({ ...d, sponsors:[...d.sponsors, ns] }));
      await sb.from("sponsors").insert({ id:ns.id, name:ns.name, tier:ns.tier, logo:ns.logo||"", description:ns.desc||"", web:ns.web||"" });
      toast("Sponsor dodany!");
    }
    setShowForm(false);
    setEditSp(null);
    setForm({ name:"", tier:"Silver", logo:"", desc:"", web:"" });
  }

  async function delSponsor(id) {
    setData(d => ({ ...d, sponsors: d.sponsors.filter(s => s.id !== id) }));
    await sb.from("sponsors").delete().eq("id", id);
    toast("Sponsor usunięty");
  }

  return (
    <div className="fade-stagger">
      <SHead title="SPONSORZY" sub="Nasi partnerzy i wspierający"
        action={isAdmin && <Btn size="sm" onClick={() => { setForm({ name:"", tier:"Silver", logo:"", desc:"", web:"" }); setEditSp(null); setShowForm(true); }}><IPlus /> DODAJ</Btn>}
      />

      {["Platinum","Gold","Silver"].map(tier => {
        const list = data.sponsors.filter(s => s.tier === tier);
        const col  = TC[tier];
        if (!list.length) return null;
        return (
          <div key={tier} style={{ marginBottom:26 }}>
            <div style={{ display:"flex", alignItems:"center", gap:9, marginBottom:13 }}>
              <div style={{ width:9, height:9, borderRadius:"50%", background:col, flexShrink:0, boxShadow:"0 0 10px " + col + "88" }} />
              <span style={{ fontFamily:FT, fontSize:10, letterSpacing:3, color:col, fontWeight:700, textTransform:"uppercase" }}>{tier}</span>
              <div style={{ flex:1, height:1, background:col + "22" }} />
            </div>
            {list.map(s => (
              <Card key={s.id} sx={{ marginBottom:11, padding:"16px 17px", border:"1px solid " + col + "30" }}>
                <div style={{ display:"flex", gap:14, alignItems:"center" }}>
                  <div style={{ width:50, height:50, borderRadius:12, background:col + "18", border:"2px solid " + col + "40", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:FT, fontWeight:900, fontSize:13, color:col, flexShrink:0 }}>
                    {(s.logo || s.name.slice(0, 2)).toUpperCase()}
                  </div>
                  <div style={{ flex:1, minWidth:0 }}>
                    <div style={{ fontFamily:FT, fontSize:15, fontWeight:700, letterSpacing:0.6, textTransform:"uppercase" }}>{s.name}</div>
                    <div style={{ color:SUB, fontSize:13, marginTop:2 }}>{s.desc}</div>
                    {s.web && <a href={s.web} target="_blank" rel="noreferrer" style={{ color:col, fontSize:11, marginTop:5, display:"block", textDecoration:"none" }}>{s.web.replace("https://", "")}</a>}
                  </div>
                  {isAdmin && (
                    <div style={{ display:"flex", gap:6, flexShrink:0 }}>
                      <button onClick={() => { setForm({ ...s }); setEditSp(s); setShowForm(true); }}
                        style={{ background:SURF2, border:"1px solid " + BDR, color:SUB, borderRadius:8, padding:"7px 9px", cursor:"pointer", display:"flex" }}><IEdit /></button>
                      <button onClick={() => delSponsor(s.id)}
                        style={{ background:REDD, border:"1px solid " + REDB, color:RED, borderRadius:8, padding:"7px 9px", cursor:"pointer", display:"flex" }}><ITrash /></button>
                    </div>
                  )}
                </div>
              </Card>
            ))}
          </div>
        );
      })}

      {data.sponsors.length === 0 && (
        <div style={{ color:MUTED, textAlign:"center", padding:"44px 0", fontSize:14 }}>
          <div style={{ fontSize:36, marginBottom:13 }}>🤝</div>
          {isAdmin ? "Dodaj pierwszego sponsora!" : "Brak sponsorów"}
        </div>
      )}

      {showForm && (
        <Sheet title={editSp ? "EDYTUJ SPONSORA" : "NOWY SPONSOR"} onClose={() => { setShowForm(false); setEditSp(null); }}>
          <TInput label="Nazwa firmy" value={form.name} onChange={sf("name")} placeholder="Firma XYZ" />
          <TInput label="Skrot / logo (2-3 litery)" value={form.logo} onChange={sf("logo")} placeholder="XYZ" />
          <TSel label="Poziom sponsoringu" value={form.tier} onChange={sf("tier")} opts={["Platinum","Gold","Silver"]} />
          <TInput label="Opis działalności" value={form.desc} onChange={sf("desc")} placeholder="Producent odziezy sportowej" />
          <TInput label="Strona www" value={form.web} onChange={sf("web")} placeholder="https://..." />
          <div style={{ display:"flex", gap:11, marginTop:6 }}>
            <Btn full onClick={saveSponsor}>{editSp ? "ZAPISZ ZMIANY" : "DODAJ SPONSORA"}</Btn>
            <Btn full v="ghost" onClick={() => { setShowForm(false); setEditSp(null); }}>ANULUJ</Btn>
          </div>
        </Sheet>
      )}

      <SocialFooter site={data.site} />
    </div>
  );
}

